using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
namespace PowerShapeBridge {
 internal static class OwnedSurfaceSetTranslationTests {
  static void Need(bool v,string e){if(!v)throw new InvalidOperationException(e);}
  static Dictionary<string,object> Clone(object v){return Program.Json.Deserialize<Dictionary<string,object>>(Program.Json.Serialize(v));}
  internal sealed class Context:OwnedTranslation.IContext,OwnedSelection.IContext,NativeSurfaceSampling.IContext {
   internal Dictionary<string,object> Snapshot,Listing;internal string Fault;internal int Calls;readonly HashSet<int> moved=new HashSet<int>();
   public Dictionary<string,object> Observation(){return Clone(Snapshot);}public Dictionary<string,object> Windows(){return Clone(Listing);}public void ConfirmDocument(){}public void Dispose(){}
   public int Composite(int t,int n){Need(t==21,"Set called another native type");return 420000000+n;}public int SelectionCount(){return 0;}
   public double[] Bounds(int id){throw new InvalidOperationException("Set requested unavailable bounds");}public void ChangeSelection(OwnedSelectionProgram p){throw new InvalidOperationException("Set changed selection");}
   public object ModelItems(){return EntitySets.Inventory(Snapshot).Select(e=>Composite(21,(int)e["nativeId"])).ToArray();}public object SelectedItems(){throw new InvalidOperationException("Do not infer empty selection from null");}
   public object ItemData(object ids){var keys=((int[])ids).Select(i=>i-420000000).ToArray();return new object[]{keys.Select(i=>21).ToArray(),keys,keys.Select(i=>(string)EntitySets.Inventory(Snapshot).Single(e=>Equals(e["nativeId"],i))["name"]).ToArray(),keys.Select(i=>0).ToArray()};}
   public object SurfacePoints(string name,double ts,double te,int td,double us,double ue,int ud){int id=(int)EntitySets.Inventory(Snapshot).Single(e=>Equals(e["name"],name))["nativeId"],n=(td+1)*(ud+1);var points=Enumerable.Range(0,n*3).Select(i=>i+id+0.33333333333333337).ToArray();var normals=Enumerable.Range(0,n*3).Select(i=>i%3==2?1.0:0.0).ToArray();if(moved.Contains(id))for(int i=0;i<n;i++)points[i*3]+=1;if(Calls>0&&((Fault=="first_post_drift"&&id==8)||(Fault=="other_drift"&&id==10)))points[0]+=0.01;if(Calls>0&&Fault=="normal_drift")normals[0]=0.1;return new object[]{0,points,normals,Enumerable.Repeat(true,n).ToArray()};}
   public int Translate(int composite,double[] vector){Need(composite==420000008+Calls&&vector.SequenceEqual(new[]{1.0,0,0}),"Wrong/repeated target or vector");Calls++;moved.Add(composite-420000000);if(Fault==(Calls==1?"throw_first":"throw_second"))throw new IOException("Lost returned step");return Fault==(Calls==1?"zero_first":"zero_second")?0:1;}
  }
  internal static int Run(){Need(File.Exists(Path.Combine(Program.Root,".surface-set-translation-fixture")),"Explicit isolated surface-set marker required; never CAD.");var rows=new List<object>();foreach(string fault in new[]{"control","throw_first","zero_first","throw_second","zero_second","first_post_drift","other_drift","normal_drift","step_tamper","execute_only"}){
   var f=new OwnedOperationPlanTests.Fixture(true,true,true,false,true);var c=new Context{Snapshot=Clone(f.Snapshot),Listing=Clone(f.Listing),Fault=fault};var args=OwnedTranslationTests.Handle(f);args["surfaceGrid"]=new Dictionary<string,object>{{"tStart",1},{"tEnd",2},{"tDivisions",2},{"uStart",1},{"uEnd",2},{"uDivisions",3}};
   var legacy=OwnedTranslation.Execute(f.Root,Guid.NewGuid().ToString("N"),args,c,true);Need(Equals(legacy["state"],"owned_translation_rejected_before_change")&&c.Calls==0,"Singleton admitted a set");
   string id=Guid.NewGuid().ToString("N");var x=OwnedTranslation.Execute(f.Root,id,args,c,true,false,false,true);bool returned=fault=="control"||fault=="step_tamper"||fault=="execute_only";Need(Equals(x["state"],returned?"owned_surface_set_translation_executed_unverified":"owned_surface_set_translation_outcome_unknown"),Program.Json.Serialize(x));int expected=fault=="control"||fault=="step_tamper"||fault=="execute_only"||fault=="throw_second"||fault=="zero_second"?2:1;Need(c.Calls==expected&&Equals(x["commandCallsAttempted"],expected),"Incorrect set callback count");
   string sha=NativeJournal.Freeze(Path.Combine(f.Root,"responses",id+".json"),x),fence=OwnedTranslation.FencePath(f.Root,(string)x["copyId"]);Need(File.Exists(fence),"Set must remain fenced before independent verification");Need(Equals(OwnedTranslation.Execute(f.Root,Guid.NewGuid().ToString("N"),args,c,true,false,false,true)["state"],"owned_surface_set_translation_rejected_before_change")&&c.Calls==expected,"Set replay reached callback");
   DateTime stamp=DateTime.UtcNow;if(returned){var j=NativeJournal.ForVerification(f.Root,id,(string)x["planSha256"]);if(stamp<=j.CommandReturnedUtc)stamp=j.CommandReturnedUtc.AddTicks(1);}var o=c.Observation();o["timestampUtc"]=stamp.ToString("o");var w=c.Windows();w["state"]="documents_listed_verified";w["timestampUtc"]=stamp.AddTicks(1).ToString("o");string iid=Guid.NewGuid().ToString("N"),lid=Guid.NewGuid().ToString("N");var va=new Dictionary<string,object>{{"executionRequestId",id},{"executionReceiptSha256",sha},{"inspectionRequestId",iid},{"inspectionSha256",NativeJournal.Freeze(Path.Combine(f.Root,"responses",iid+".json"),o)},{"listingRequestId",lid},{"listingSha256",NativeJournal.Freeze(Path.Combine(f.Root,"responses",lid+".json"),w)},{"windowNumber",1},{"modelId",9},{"expiresUtc",stamp.AddSeconds(150).ToString("o")}};
   Need(Equals(OwnedTranslation.Verify(f.Root,va,c,true)["state"],"owned_translation_verification_rejected"),"Singleton verifier accepted set receipt");if(fault=="step_tamper")File.AppendAllText(Path.Combine(f.Root,"surfacesetsteps",id,"0000.observed.json")," ");var v=fault=="execute_only"?null:OwnedTranslation.Verify(f.Root,va,c,true,false,false,true);if(v!=null)Need(Equals(v["state"],fault=="control"?"owned_surface_set_translation_verified_observed":"owned_surface_set_translation_verification_rejected"),Program.Json.Serialize(v));string vid=null,vsha=null;if(v!=null){vid=Guid.NewGuid().ToString("N");v["bridgeRequestId"]=vid;vsha=NativeJournal.Freeze(Path.Combine(f.Root,"responses",vid+".json"),v);}Need(File.Exists(fence)!=(fault=="control")&&c.Calls==expected,"Set verifier released an unproved fence or replayed");rows.Add(new{fault,root=f.Root,executionId=id,executionSha256=sha,calls=c.Calls,verificationArguments=va,verificationId=vid,verificationSha256=vsha,verificationResult=v,arguments=args,execution=x});
  }Directory.CreateDirectory(Path.Combine(Program.Root,"reports"));NativeJournal.Freeze(Path.Combine(Program.Root,"reports","surface-set-translation-tests.json"),new{state="passed",cases=rows.Count,rows,cadConnectionAttempted=false});Console.WriteLine("PASS: "+rows.Count+" surface-set exact targets/partial steps/lost return/no replay/non-target/tamper guards; no CAD.");return rows.Count;}
 }
}
